typedef double (*FunctionPtr)(double);

double simpson_integration(FunctionPtr f, double a, double b, int N) {
    if (N <= 0 || N % 2 != 0) {
        return 0.0; // N must be even and positive
    }

    double h = (b - a) / N;
    double sum = f(a) + f(b);

    for (int i = 1; i < N; i++) {
        double x = a + i * h;
        if (i % 2 == 0) {
            sum += 2.0 * f(x);
        } else {
            sum += 4.0 * f(x);
        }
    }

    return (h / 3.0) * sum;
}

